#!/usr/bin/env node
// Makes an app's Android project ready to build: node packages/android-native/prepare.mjs <write|reader> [--skip-web]
//
// The project is generated by Capacitor (`cap add android`) and is not committed: this script adds everything that is ours (the plugins, link
// schemes, signing, version and icons) to it, so there is one native layer for both apps and a Capacitor upgrade is a one-line change.
// Then build with `./gradlew assembleRelease` in <app>/android and take app/build/outputs/apk/release/app-release.apk (see docs/ANDROID.md).
import { spawnSync } from 'node:child_process';
import { appendFileSync, cpSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { APPS, PLUGINS, PLUGIN_PACKAGE, patchAppGradle, patchMainActivity, patchManifest, versionCode } from './lib.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../..');
const [appName, ...flags] = process.argv.slice(2);
const app = APPS[appName];
if (!app) {
  console.error(`Usage: prepare.mjs <${Object.keys(APPS).join('|')}> [--skip-web]`);
  process.exit(2);
}

const appDir = join(root, app.dir);
const run = (cmd, args) => {
  const r = spawnSync(cmd, args, { cwd: appDir, stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.status !== 0) throw new Error(`${cmd} ${args.join(' ')} failed (${r.status})`);
};

// A build that is not of `main` says so, the same way the Windows installers do (docs/VERSIONING.md): CADREL_DEV_BUILD=dev.<run number>.
const base = readFileSync(join(root, app.versionFile), 'utf8').trim();
const dev = (process.env.CADREL_DEV_BUILD ?? '').trim();
const versionName = dev ? `${base}-${dev}` : base;
const code = versionCode(versionName);

const android = join(appDir, 'android');
if (!existsSync(android)) run('npx', ['cap', 'add', 'android']);
if (!flags.includes('--skip-web')) run('npm', ['run', 'build:mobile']);
run('npx', ['cap', 'sync', 'android']);

// Our plugins.
const config = readFileSync(join(appDir, 'capacitor.config.ts'), 'utf8');
const appId = /appId:\s*'([^']+)'/.exec(config)?.[1];
if (!appId) throw new Error('Could not read appId from capacitor.config.ts');
const javaRoot = join(android, 'app/src/main/java');
const pluginDir = join(javaRoot, ...PLUGIN_PACKAGE.split('.'));
mkdirSync(pluginDir, { recursive: true });
for (const p of PLUGINS) cpSync(join(here, 'java', ...PLUGIN_PACKAGE.split('.'), `${p}.java`), join(pluginDir, `${p}.java`));

const edit = (file, patch) => {
  const path = join(android, file);
  writeFileSync(path, patch(readFileSync(path, 'utf8')));
};
edit(join('app/src/main/java', ...appId.split('.'), 'MainActivity.java'), patchMainActivity);
edit('app/src/main/AndroidManifest.xml', (s) => patchManifest(s, app.schemes));
edit('app/build.gradle', (s) => patchAppGradle(s, { versionName, versionCode: code }));

// Icons: the app's own launcher icons replace Capacitor's (and its adaptive-icon files, so the plain ones are used on every Android).
const res = join(android, 'app/src/main/res');
rmSync(join(res, 'mipmap-anydpi-v26'), { recursive: true, force: true });
for (const d of readdirSync(res).filter((n) => n.startsWith('mipmap-'))) {
  for (const f of ['ic_launcher_foreground.png']) rmSync(join(res, d, f), { force: true });
}
cpSync(join(appDir, 'build/android-res'), res, { recursive: true });

const apk = app.apk(versionName);
console.log(`\nAndroid project ready: ${appId} ${versionName} (version code ${code}) -> ${apk}`);
if (process.env.GITHUB_OUTPUT) appendFileSync(process.env.GITHUB_OUTPUT, `version=${versionName}\nversion_code=${code}\napk=${apk}\napp_dir=${app.dir}\n`);
